/**
 * All user-facing strings for the website, member app, and admin console.
 *
 * The product is English only (no i18next). Keep every visible string here so copy can be
 * reviewed and replaced in one place. Functions are used where a string needs values.
 *
 * These are engine strings: they never name a property. Text that depends on the property uses
 * `{token}` placeholders filled from the active property at render time (`useProperty().fill`
 * or `fill` from property/current.js): `{name}`, `{price}`, `{interval}`, `{minimumAge}`,
 * `{owner}`, `{id}`, and the others listed in `propertyTokens` (@trelliskit/shared). Marketing
 * copy lives in the property's web/content/*.md files, not here.
 */

